// Verifikasi tanda tangan HMAC dan usia timestamp (BRD 4.4, AC-31).
// Secret diambil dari environment n8n, tidak ditulis di dalam alur ini.
const crypto = require('crypto');

const SECRET = $env.N8N_HMAC_SECRET;
const TOLERANCE_SECONDS = Number($env.N8N_TIMESTAMP_TOLERANCE_SECONDS || 300);

if (!SECRET) {
  throw new Error('N8N_HMAC_SECRET belum diisi pada environment n8n.');
}

const item = $input.first();
const headers = item.json.headers || {};
const rawBody = item.json.body;
const bodyText = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);

const signature = headers['x-signature'];
const timestamp = headers['x-timestamp'];

if (!signature || !timestamp) {
  return [{ json: { ok: false, status: 401, reason: 'header tanda tangan tidak lengkap' } }];
}

const skew = Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp));
if (!Number.isFinite(skew) || skew > TOLERANCE_SECONDS) {
  return [{ json: { ok: false, status: 401, reason: `selisih waktu ${skew} detik` } }];
}

const expected = crypto
  .createHmac('sha256', SECRET)
  .update(`${timestamp}.${bodyText}`)
  .digest('hex');

const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const valid = a.length === b.length && crypto.timingSafeEqual(a, b);

if (!valid) {
  return [{ json: { ok: false, status: 401, reason: 'tanda tangan tidak cocok' } }];
}

const payload = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;

return [{ json: { ok: true, status: 200, payload } }];

